CREATE TABLE IF NOT EXISTS _migration_119_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_119_guard;
INSERT INTO _migration_119_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM topics WHERE id LIKE 'topic_was_commerce_%' OR id LIKE 'topic_was_irs_%' OR id LIKE 'topic_was_elect_%') = 24 AND (SELECT COUNT(*) FROM syllabus_topics WHERE specification_id IN ('spec_wassce_commerce_waec','spec_wassce_irs_waec','spec_wassce_elect_app_waec')) = 24 THEN 1 ELSE 0 END;
DROP TABLE _migration_119_guard;
